var TURNSTILE_SECRET = process.env.TURNSTILE_SECRET_KEY;
var TURNSTILE_VERIFY_URL = "https://challenges.cloudflare.com/turnstile/v0/siteverify";
async function verifyTurnstile(req, res, next) {
  if (!TURNSTILE_SECRET) {
    next();
    return;
  }
  const token = req.body?.turnstileToken;
  if (!token) {
    res.status(400).json({ success: false, message: "Verifica CAPTCHA richiesta" });
    return;
  }
  if (token === "__turnstile_not_configured__") {
    next();
    return;
  }
  try {
    const response = await fetch(TURNSTILE_VERIFY_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        secret: TURNSTILE_SECRET,
        response: token,
        remoteip: req.ip || ""
      })
    });
    const result = await response.json();
    if (!result.success) {
      res.status(403).json({ success: false, message: "Verifica CAPTCHA fallita. Riprova." });
      return;
    }
    next();
  } catch (error46) {
    console.error("Turnstile verification error:", error46);
    next();
  }
}

