async function getRoster(leagueId, userId, targetMemberId) {
  const member = await prisma.leagueMember.findFirst({
    where: {
      leagueId,
      userId,
      status: MemberStatus7.ACTIVE
    }
  });
  if (!member) {
    return { success: false, message: "Non sei membro di questa lega" };
  }
  const memberId = targetMemberId || member.id;
  const roster = await prisma.playerRoster.findMany({
    where: {
      leagueMemberId: memberId,
      status: "ACTIVE"
    },
    include: {
      player: true,
      contract: true
    },
    orderBy: [
      { player: { position: "asc" } },
      { player: { name: "asc" } }
    ]
  });
  const targetMember = await prisma.leagueMember.findUnique({
    where: { id: memberId },
    include: {
      user: {
        select: { username: true }
      },
      league: true
    }
  });
  const allPlayerIds = roster.map((r) => r.playerId);
  const statsMap = await computeSeasonStatsBatch(allPlayerIds);
  const enriched = roster.map((r) => ({
    ...r,
    player: {
      ...r.player,
      computedStats: statsMap.get(r.playerId) || null
    }
  }));
  const grouped = {
    P: enriched.filter((r) => r.player.position === "P"),
    D: enriched.filter((r) => r.player.position === "D"),
    C: enriched.filter((r) => r.player.position === "C"),
    A: enriched.filter((r) => r.player.position === "A")
  };
  return {
    success: true,
    data: {
      member: targetMember,
      roster: grouped,
      totals: {
        P: grouped.P.length,
        D: grouped.D.length,
        C: grouped.C.length,
        A: grouped.A.length,
        total: roster.length
      },
      slots: {
        P: targetMember?.league.goalkeeperSlots || 3,
        D: targetMember?.league.defenderSlots || 8,
        C: targetMember?.league.midfielderSlots || 8,
        A: targetMember?.league.forwardSlots || 6
      }
    }
  };
}
