async function setFirstMarketTurnOrder(sessionId, adminUserId, memberOrder) {
  const session = await prisma.marketSession.findUnique({
    where: { id: sessionId },
    include: { league: true }
  });
  if (!session) {
    return { success: false, message: "Sessione non trovata" };
  }
  if (session.type !== "PRIMO_MERCATO") {
    return { success: false, message: "Questa funzione \xE8 solo per il PRIMO MERCATO" };
  }
  const admin = await prisma.leagueMember.findFirst({
    where: {
      leagueId: session.leagueId,
      userId: adminUserId,
      role: MemberRole2.ADMIN,
      status: MemberStatus7.ACTIVE
    }
  });
  if (!admin) {
    return { success: false, message: "Non autorizzato" };
  }
  const members = await prisma.leagueMember.findMany({
    where: {
      leagueId: session.leagueId,
      status: MemberStatus7.ACTIVE
    }
  });
  const memberIds = members.map((m) => m.id);
  const invalidIds = memberOrder.filter((id) => !memberIds.includes(id));
  if (invalidIds.length > 0) {
    return { success: false, message: `ID membri non validi: ${invalidIds.join(", ")}` };
  }
  if (memberOrder.length !== memberIds.length) {
    return { success: false, message: "L'ordine deve includere tutti i membri attivi" };
  }
  await prisma.marketSession.update({
    where: { id: sessionId },
    data: {
      turnOrder: memberOrder,
      currentTurnIndex: 0,
      currentRole: "P"
      // Inizia dai portieri
    }
  });
  for (let i = 0; i < memberOrder.length; i++) {
    await prisma.leagueMember.update({
      where: { id: memberOrder[i] },
      data: { firstMarketOrder: i }
    });
  }
  const firstNominator = members.find((m) => m.id === memberOrder[0]);
  if (firstNominator) {
    const nominatorUser = await prisma.user.findUnique({
      where: { id: firstNominator.userId },
      select: { username: true }
    });
    void triggerAuctionStarted(sessionId, {
      sessionId,
      auctionType: session.type,
      nominatorId: firstNominator.id,
      nominatorName: nominatorUser?.username ?? "",
      timestamp: (/* @__PURE__ */ new Date()).toISOString()
    });
  }
  return {
    success: true,
    message: "Ordine turni impostato",
    data: { turnOrder: memberOrder, currentRole: "P" }
  };
}
