async function markReadyToResume(auctionId, userId) {
  const auction = await prisma.auction.findUnique({
    where: { id: auctionId },
    include: { marketSession: true }
  });
  if (!auction) {
    return { success: false, message: "Asta non trovata" };
  }
  if (auction.status !== AuctionStatus.AWAITING_RESUME) {
    return { success: false, message: "L'asta non \xE8 in attesa di ripresa" };
  }
  const member = await prisma.leagueMember.findFirst({
    where: { leagueId: auction.leagueId, userId, status: MemberStatus7.ACTIVE }
  });
  if (!member) {
    return { success: false, message: "Non sei membro di questa lega" };
  }
  const currentReady = auction.resumeReadyMembers || [];
  if (currentReady.includes(member.id)) {
    return { success: false, message: "Hai gi\xE0 confermato di essere pronto" };
  }
  const newReady = [...currentReady, member.id];
  const allMembers = await prisma.leagueMember.findMany({
    where: { leagueId: auction.leagueId, status: MemberStatus7.ACTIVE }
  });
  const allReady = newReady.length >= allMembers.length;
  if (allReady) {
    await prisma.auction.update({
      where: { id: auctionId },
      data: {
        status: AuctionStatus.ACTIVE,
        resumeReadyMembers: newReady,
        timerExpiresAt: new Date(Date.now() + (auction.timerSeconds || 30) * 1e3)
      }
    });
    if (auction.marketSession?.currentPhase === "ASTA_SVINCOLATI") {
      await prisma.marketSession.update({
        where: { id: auction.marketSessionId },
        data: {
          svincolatiState: "AUCTION",
          svincolatiTimerStartedAt: /* @__PURE__ */ new Date()
        }
      });
    }
    if (auction.marketSessionId) {
      void triggerAuctionResumed(auction.marketSessionId, {
        sessionId: auction.marketSessionId,
        auctionId: auction.id,
        timestamp: (/* @__PURE__ */ new Date()).toISOString()
      });
    }
    return {
      success: true,
      message: "Tutti pronti! L'asta riprende.",
      data: { allReady: true }
    };
  } else {
    await prisma.auction.update({
      where: { id: auctionId },
      data: { resumeReadyMembers: newReady }
    });
    if (auction.marketSessionId) {
      void triggerAuctionStateChanged(auction.marketSessionId, {
        sessionId: auction.marketSessionId,
        auctionId,
        reason: "resume-ready-progress",
        timestamp: (/* @__PURE__ */ new Date()).toISOString()
      });
    }
    return {
      success: true,
      message: "Pronto registrato. In attesa degli altri manager.",
      data: { allReady: false, ready: newReady.length, total: allMembers.length }
    };
  }
}
