async function getRubataPreferences(leagueId, userId) {
  const member = await prisma.leagueMember.findFirst({
    where: {
      leagueId,
      userId,
      status: MemberStatus10.ACTIVE
    }
  });
  if (!member) {
    return { success: false, message: "Non sei membro di questa lega" };
  }
  let session = await prisma.marketSession.findFirst({
    where: {
      leagueId,
      status: "ACTIVE",
      currentPhase: "RUBATA"
    }
  });
  if (!session) {
    session = await prisma.marketSession.findFirst({
      where: {
        leagueId,
        status: "ACTIVE"
      }
    });
  }
  if (!session) {
    session = await prisma.marketSession.findFirst({
      where: { leagueId },
      orderBy: { createdAt: "desc" }
    });
  }
  if (!session) {
    return { success: false, message: "Nessuna sessione trovata per questa lega" };
  }
  const preferences = await prisma.rubataPreference.findMany({
    where: {
      sessionId: session.id,
      memberId: member.id
    },
    include: {
      player: {
        select: {
          id: true,
          name: true,
          team: true,
          position: true,
          quotation: true
        }
      }
    },
    orderBy: [
      { priority: "asc" },
      { createdAt: "desc" }
    ]
  });
  return {
    success: true,
    data: {
      preferences,
      sessionId: session.id,
      memberId: member.id
    }
  };
}
async function setRubataPreference(leagueId, userId, playerId, preference) {
  const member = await prisma.leagueMember.findFirst({
    where: {
      leagueId,
      userId,
      status: MemberStatus10.ACTIVE
    }
  });
  if (!member) {
    return { success: false, message: "Non sei membro di questa lega" };
  }
  let session = await prisma.marketSession.findFirst({
    where: {
      leagueId,
      status: "ACTIVE",
      currentPhase: "RUBATA"
    }
  });
  if (session) {
    const blockedStates = ["OFFERING", "AUCTION"];
    if (blockedStates.includes(session.rubataState || "")) {
      return { success: false, message: "Non puoi modificare le preferenze durante l'asta attiva" };
    }
  }
  if (!session) {
    session = await prisma.marketSession.findFirst({
      where: {
        leagueId,
        status: "ACTIVE"
      }
    });
  }
  if (!session) {
    session = await prisma.marketSession.findFirst({
      where: { leagueId },
      orderBy: { createdAt: "desc" }
    });
  }
  if (!session) {
    return { success: false, message: "Nessuna sessione trovata per questa lega" };
  }
  const player = await prisma.serieAPlayer.findUnique({
    where: { id: playerId }
  });
  if (!player) {
    return { success: false, message: "Giocatore non trovato" };
  }
  const result = await prisma.rubataPreference.upsert({
    where: {
      sessionId_memberId_playerId: {
        sessionId: session.id,
        memberId: member.id,
        playerId
      }
    },
    create: {
      sessionId: session.id,
      memberId: member.id,
      playerId,
      isWatchlist: preference.isWatchlist ?? false,
      isAutoPass: preference.isAutoPass ?? false,
      maxBid: preference.maxBid,
      priority: preference.priority,
      notes: preference.notes,
      watchlistCategory: preference.watchlistCategory
    },
    update: {
      isWatchlist: preference.isWatchlist,
      isAutoPass: preference.isAutoPass,
      maxBid: preference.maxBid,
      priority: preference.priority,
      notes: preference.notes,
      watchlistCategory: preference.watchlistCategory
    },
    include: {
      player: {
        select: {
          id: true,
          name: true,
          team: true,
          position: true
        }
      }
    }
  });
  return {
    success: true,
    message: "Preferenza salvata",
    data: result
  };
}
