async function migrateProphecies(leagueId, adminUserId) {
  const adminMember = await prisma.leagueMember.findFirst({
    where: {
      leagueId,
      userId: adminUserId,
      role: "ADMIN",
      status: MemberStatus11.ACTIVE
    }
  });
  if (!adminMember) {
    return { success: false, message: "Non autorizzato" };
  }
  const acknowledgments = await prisma.auctionAcknowledgment.findMany({
    where: {
      prophecy: { not: null },
      auction: { leagueId }
    },
    include: {
      auction: {
        include: {
          player: true
        }
      },
      member: true
    }
  });
  let migrated = 0;
  let skipped = 0;
  const errors = [];
  for (const ack of acknowledgments) {
    if (!ack.prophecy?.trim()) {
      skipped++;
      continue;
    }
    const movement = await prisma.playerMovement.findFirst({
      where: {
        auctionId: ack.auctionId
      }
    });
    if (!movement) {
      errors.push(`Nessun movimento trovato per asta ${ack.auctionId}`);
      continue;
    }
    const isBuyer = movement.toMemberId === ack.memberId;
    const isSeller = movement.fromMemberId === ack.memberId;
    if (!isBuyer && !isSeller) {
      skipped++;
      continue;
    }
    const existingProphecy = await prisma.prophecy.findUnique({
      where: {
        movementId_authorId: {
          movementId: movement.id,
          authorId: ack.memberId
        }
      }
    });
    if (existingProphecy) {
      skipped++;
      continue;
    }
    try {
      await prisma.prophecy.create({
        data: {
          leagueId,
          playerId: ack.auction.playerId,
          authorId: ack.memberId,
          movementId: movement.id,
          authorRole: isBuyer ? ProphecyRole2.BUYER : ProphecyRole2.SELLER,
          content: ack.prophecy.trim(),
          createdAt: ack.acknowledgedAt
        }
      });
      migrated++;
    } catch (error46) {
      errors.push(`Errore migrazione profezia per asta ${ack.auctionId}: ${error46 instanceof Error ? error46.message : String(error46)}`);
    }
  }
  return {
    success: true,
    message: `Migrazione completata: ${migrated} profezie migrate, ${skipped} saltate`,
    data: {
      migrated,
      skipped,
      errors: errors.length > 0 ? errors : void 0
    }
  };
}
async function assignPrize(leagueId, adminUserId, memberId, amount, reason) {
  const adminMember = await prisma.leagueMember.findFirst({
    where: {
      leagueId,
      userId: adminUserId,
      role: "ADMIN",
      status: MemberStatus11.ACTIVE
    }
  });
  if (!adminMember) {
    return { success: false, message: "Non autorizzato" };
  }
  if (!Number.isInteger(amount) || amount <= 0) {
    return { success: false, message: "L'importo deve essere un numero intero positivo" };
  }
  const targetMember = await prisma.leagueMember.findFirst({
    where: {
      id: memberId,
      leagueId,
      status: MemberStatus11.ACTIVE
    },
    include: {
      user: { select: { username: true } }
    }
  });
  if (!targetMember) {
    return { success: false, message: "Manager non trovato" };
  }
  const [updatedMember, prize] = await prisma.$transaction([
    prisma.leagueMember.update({
      where: { id: memberId },
      data: {
        currentBudget: { increment: amount }
      }
    }),
    prisma.prize.create({
      data: {
        leagueId,
        memberId,
        adminId: adminMember.id,
        amount,
        reason: reason || null
      }
    })
  ]);
  return {
    success: true,
    message: `Premio di ${amount}M assegnato a ${targetMember.teamName ?? "squadra"}${reason ? ` (${reason})` : ""}`,
    data: {
      memberId,
      teamName: targetMember.teamName,
      username: targetMember.user.username,
      amount,
      reason,
      newBudget: updatedMember.currentBudget,
      prizeId: prize.id
    }
  };
}
