  const turnOrder = session.svincolatiTurnOrder || [];
  const passedMembers = session.svincolatiPassedMembers || [];
  const finishedMembers = session.svincolatiFinishedMembers || [];
  const currentTurnIndex = session.svincolatiCurrentTurnIndex ?? 0;
