async function declareSvincolatiFinished(leagueId, userId) {
  const member = await prisma.leagueMember.findFirst({
    where: {
      leagueId,
      userId,
      status: MemberStatus12.ACTIVE
    }
  });
  if (!member) {
    return { success: false, message: "Non sei membro di questa lega" };
  }
  const activeSession = await prisma.marketSession.findFirst({
    where: {
      leagueId,
      status: "ACTIVE",
      currentPhase: "ASTA_SVINCOLATI"
    }
  });
  if (!activeSession) {
    return { success: false, message: "Nessuna sessione svincolati attiva" };
  }
  const finishedMembers = activeSession.svincolatiFinishedMembers || [];
  if (finishedMembers.includes(member.id)) {
    return { success: false, message: "Hai gi\xE0 dichiarato di aver finito" };
  }
  const newFinishedMembers = [...finishedMembers, member.id];
  await prisma.marketSession.update({
    where: { id: activeSession.id },
    data: {
      svincolatiFinishedMembers: newFinishedMembers
    }
  });
  logAction(userId, leagueId, "SVINCOLATI_DECLARE_FINISHED", "MarketSession", activeSession.id, void 0, { memberId: member.id }).catch(() => {
  });
  const allMembers = await prisma.leagueMember.findMany({
    where: { leagueId, status: MemberStatus12.ACTIVE }
  });
  const allFinished = newFinishedMembers.length >= allMembers.length;
  return {
    success: true,
    message: allFinished ? "Tutti i manager hanno finito! L'admin pu\xF2 chiudere la fase." : "Hai dichiarato di aver finito. Non potrai pi\xF9 fare offerte.",
    data: {
      finishedCount: newFinishedMembers.length,
      totalMembers: allMembers.length,
      allFinished
    }
  };
}
async function undoSvincolatiFinished(leagueId, userId) {
  const member = await prisma.leagueMember.findFirst({
    where: {
      leagueId,
      userId,
      status: MemberStatus12.ACTIVE
    }
  });
  if (!member) {
    return { success: false, message: "Non sei membro di questa lega" };
  }
  const activeSession = await prisma.marketSession.findFirst({
    where: {
      leagueId,
      status: "ACTIVE",
      currentPhase: "ASTA_SVINCOLATI"
    }
  });
  if (!activeSession) {
    return { success: false, message: "Nessuna sessione svincolati attiva" };
  }
  const finishedMembers = activeSession.svincolatiFinishedMembers || [];
  if (!finishedMembers.includes(member.id)) {
    return { success: false, message: "Non hai ancora dichiarato di aver finito" };
  }
  const newFinishedMembers = finishedMembers.filter((id) => id !== member.id);
  await prisma.marketSession.update({
    where: { id: activeSession.id },
    data: {
      svincolatiFinishedMembers: newFinishedMembers
    }
  });
  logAction(userId, leagueId, "SVINCOLATI_UNDO_FINISHED", "MarketSession", activeSession.id, void 0, { memberId: member.id }).catch(() => {
  });
  return {
    success: true,
    message: "Puoi tornare a fare offerte."
  };
}
